def compare_versions(a: str, b: str) -> int:
    def parse_version(version_str: str):
        # Remove build metadata (everything after +)
        version_str = version_str.split('+')[0]

        # Split into version and prerelease parts
        if '-' in version_str:
            version_part, prerelease_part = version_str.split('-', 1)
            prerelease = prerelease_part.split('.')
        else:
            version_part = version_str
            prerelease = None

        # Parse major.minor.patch
        parts = version_part.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        return (major, minor, patch, prerelease)

    def compare_prerelease(pre_a, pre_b):
        # If neither has prerelease, they're equal (in this context)
        if pre_a is None and pre_b is None:
            return 0
        # If only one has prerelease, the one without is higher
        if pre_a is None:
            return 1
        if pre_b is None:
            return -1

        # Both have prerelease, compare identifier by identifier
        for i in range(max(len(pre_a), len(pre_b))):
            if i >= len(pre_a):
                # pre_a has fewer identifiers, so it's lower
                return -1
            if i >= len(pre_b):
                # pre_b has fewer identifiers, so pre_a is higher
                return 1

            id_a, id_b = pre_a[i], pre_b[i]

            # Check if identifiers are numeric
            is_num_a = id_a.isdigit()
            is_num_b = id_b.isdigit()

            if is_num_a and is_num_b:
                # Both numeric: compare numerically
                num_a, num_b = int(id_a), int(id_b)
                if num_a < num_b:
                    return -1
                if num_a > num_b:
                    return 1
            elif is_num_a:
                # Only id_a is numeric: numeric < non-numeric
                return -1
            elif is_num_b:
                # Only id_b is numeric: non-numeric > numeric
                return 1
            else:
                # Both non-numeric: compare lexically
                if id_a < id_b:
                    return -1
                if id_a > id_b:
                    return 1

        return 0

    major_a, minor_a, patch_a, pre_a = parse_version(a)
    major_b, minor_b, patch_b, pre_b = parse_version(b)

    # Compare major.minor.patch numerically
    if major_a != major_b:
        return -1 if major_a < major_b else 1
    if minor_a != minor_b:
        return -1 if minor_a < minor_b else 1
    if patch_a != patch_b:
        return -1 if patch_a < patch_b else 1

    # Compare prerelease versions
    return compare_prerelease(pre_a, pre_b)
